'use strict';
const EX=window.EXAMS;
function examState(y){if(!state.exams[y])state.exams[y]={listening:{},grammar:{},writing:'',plan:'',self:{},submitted:false,timer:null};return state.exams[y];}
function examFilled(y){const s=examState(y);return Object.values(s.listening).filter(v=>Array.isArray(v)?v.length:String(v).trim()).length+Object.values(s.grammar).filter(v=>String(v).trim()).length+(s.writing.trim()?1:0);}
function onlineExamLibrary(){return head('Deine Originaltests. Online ausfüllbar.','Erst Grammatik üben, dann einen ganzen Test bearbeiten. Hörverstehen und Textproduktion gibt es ausschließlich hier.','Klasse 7 · 2021–2025')+`<section class="panel tint"><h2>Eine echte Generalprobe</h2><p>Alle drei Teile sind enthalten: Listening, Use of English und Textproduktion. Die Originale sehen 50 Minuten und insgesamt 60 BE vor.</p><p class="meta">Deine Antworten bleiben auf diesem Gerät. Die Lösungen erscheinen nach der Abgabe. Freie Hörantworten und Schreibtexte bewertest du selbst mit den offiziellen Hinweisen.</p></section>${Object.values(EX).reverse().map(e=>{const s=examState(e.year),n=examFilled(e.year);return `<article class="exam-library-row"><div class="exam-year">${e.year}</div><div><h2>${E(e.title)}</h2><p class="meta">Schreibauftrag: ${E(e.writingTitle)}</p><span class="pill">${s.submitted?'Abgegeben · Auswertung verfügbar':n?`${n} Antwortfelder bearbeitet`:'Noch nicht begonnen'}</span></div><a class="button ${n?'secondary':''}" href="#exam/${e.year}">${s.submitted?'Auswertung öffnen':n?'Test fortsetzen':'Test starten'}</a></article>`;}).join('')}<details style="margin-top:32px"><summary>Original-PDFs und Hördateien</summary>${Object.values(EX).reverse().map(e=>`<article class="material-row"><strong>${e.year}</strong><div class="material-links">${pdfLink(e.files.task,'Aufgaben')}${pdfLink(e.files.solution,'Offizielle Lösungen')}${pdfLink(e.files.audio,'Hördatei')}</div></article>`).join('')}</details><p class="source-note">Quelle: die bereitgestellten Jahrgangsstufentests Englisch, Gymnasium, Klasse 7. Inhalt und Antwortoptionen wurden aus den Originalen übertragen; Layout und Nummerierung der einzelnen Antwortfelder wurden für die Onlinebearbeitung angepasst. Die Hördateien sind für die Wiedergabe komprimiert; Hörtexte, Pausen und Wiederholungen bleiben vollständig erhalten. Historische Angaben beziehen sich auf das jeweilige Originaljahr. Es gibt keine Übertragung an deine Lehrkraft.</p>`;}
function onlineTest(id){const y=EX[id]?Number(id):2025,e=EX[y],s=examState(y),disabled=s.submitted?'disabled':'';return `<a class="back" href="#exams">← Alle Originaltests</a>${head('Originaltest '+y,e.title,'Klasse 7 · 50 Minuten · 60 BE')}<div class="exam-toolbar"><div class="exam-jump" aria-label="Prüfungsteile">${button('I · Listening','exam-jump:listening','secondary')}${button('II · Use of English','exam-jump:grammar','secondary')}${button('III · Textproduktion','exam-jump:writing','secondary')}</div><span id="exam-saved" role="status" class="meta">${storageOK?'Auf diesem Gerät gespeichert':'Speichern nicht verfügbar'}</span></div><section class="panel exam-info"><div><strong>Deine Generalprobe</strong><p class="meta">50 Minuten insgesamt. Keine automatische Abgabe. Bearbeite den Test ohne Nachschlagen. Der Timer ist optional.</p>${pdfLink(e.files.task,'Original-PDF zum Vergleichen')}</div><div class="timer"><output data-exam-timer="${y}" aria-label="Verbleibende Testzeit">${examTimeLabel(y)}</output>${button(s.timer?.running?'Pausieren':'Timer starten / fortsetzen','exam-timer:'+y,'secondary',disabled)}${button('Zurücksetzen','exam-reset-timer:'+y,'text',disabled)}</div></section>${s.submitted?examResults(y):''}
<details class="exam-part" id="exam-listening" open><summary><span>I · Listening Comprehension</span><span class="pill">20 BE</span></summary><h2>${E(e.title)}</h2>${audioBlock(year(y))}${e.listening.map(group=>`<section class="exam-question"><h3 lang="en">${E(group.title)}</h3>${group.image?`<img class="exam-figure" src="${group.image}" alt="${E(group.alt)}" loading="lazy"><p class="meta">Originalabbildungen. A, B, C${y===2021||y===2024?', D':''} von links nach rechts.</p>`:''}${group.items.map(item=>examListeningField(y,item)).join('')}</section>`).join('')}</details>
<details class="exam-part" id="exam-grammar"><summary><span>II · Use of English</span><span class="pill">20 BE</span></summary>${e.passages.map(p=>`<section class="exam-question"><h2>${E(p.title)}</h2><p class="meta">${p.kind==='correction'?'Alle unterstrichenen Stellen enthalten Fehler. Schreibe deine Verbesserung in das zugehörige Feld, ohne die Aussage zu verändern.':'Vervollständige den Text mit den unten angegebenen Wörtern. Aus jeder Box wird genau ein Wort oder Ausdruck verwendet. Trage die passende Auswahl in die Lücken ein.'}</p>${p.boxes?`<div class="word-boxes" aria-label="Wortboxen aus dem Original">${p.boxes.map(box=>`<ul lang="en">${box.map(v=>`<li>${E(v)}</li>`).join('')}</ul>`).join('')}</div>`:''}<div class="exam-passage" lang="en">${examPassage(y,p)}</div>${p.kind==='correction'?`<div class="correction-grid">${p.ids.map(id=>examCorrection(y,e.grammar.find(g=>g.id===id))).join('')}</div>`:''}</section>`).join('')}${s.submitted?`<h2>Deine Grammatik-Auswertung</h2>${e.grammar.map(g=>examGrammarFeedback(y,g)).join('')}`:''}</details>
<details class="exam-part" id="exam-writing"><summary><span>III · Text Production</span><span class="pill">20 BE</span></summary><div class="writing-layout"><section><h2>Originalauftrag & Material</h2><div class="exam-source">${E(e.writingSource)}</div><a href="${e.writingImage}" target="_blank" rel="noopener" aria-label="Originalmaterial vergrößern"><img class="exam-figure" src="${e.writingImage}" alt="${E(e.writingAlt)}" loading="lazy"></a>${e.writingDetails?`<details><summary>Bildinformationen als Text lesen</summary><div class="exam-source">${E(e.writingDetails)}</div></details>`:''}${pdfLink(e.files.task,'Originalseite öffnen',e.writingPage)}</section><section><h2>Deine Antwort</h2><label for="exam-plan">Planung und Stichpunkte (optional)</label><textarea id="exam-plan" class="exam-plan" data-exam="${y}" data-exam-field="plan" ${disabled}>${E(s.plan)}</textarea><div class="row"><label for="exam-writing-text"><strong>Dein englischer Text</strong></label><span class="pill" id="exam-word-count">${wordCount(s.writing)} Wörter</span></div><p class="meta">Etwa 140 Wörter laut Originalauftrag. Rechtschreibhilfe im Textfeld ausgeschaltet.</p><textarea id="exam-writing-text" data-exam="${y}" data-exam-field="writing" lang="en" spellcheck="false" ${disabled}>${E(s.writing)}</textarea>${s.submitted?`<h3>Deine Selbsteinschätzung</h3><p class="meta">Prüfe zuerst, ob alle Punkte des Auftrags erfüllt sind. Bewerte dann Aufbau, Verständlichkeit, Grammatik und Wortschatz anhand des offiziellen Rasters. Die Plattform bewertet freie Texte nicht automatisch.</p>${pdfLink(e.files.solution,'Offizielles Bewertungsraster öffnen',4)}${examSelfSelect(y,'content',4,'Inhalt & Textstruktur',.5)}${examSelfSelect(y,'language',6,'Sprache',.5)}<p class="meta">(Inhalt + Sprache) × 2 = maximal 20 BE. Für eine verlässliche Einschätzung ist Feedback deiner Lehrkraft hilfreich.</p>`:''}</section></div></details>
<section class="panel exam-finish"><h2>${s.submitted?'Dein Antwortbogen bleibt gespeichert.':'Bereit für die Auswertung?'}</h2><p class="meta">${s.submitted?'Du kannst den Antwortbogen herunterladen oder den Test weiter bearbeiten.':'Erst abgeben, dann die Lösungen ansehen. Freie Antworten schätzt du selbst ein.'}</p><div class="actions">${s.submitted?button('Antworten weiter bearbeiten','exam-edit:'+y):button('Test abgeben & auswerten','exam-submit:'+y)}${button('Antwortbogen herunterladen','exam-export:'+y,'secondary')}<a href="#exams">Speichern & später weiter</a></div></section>`;}
function examListeningField(y,item){const s=examState(y),value=s.listening[item.id],disabled=s.submitted?'disabled':'';const id='el-'+item.id;let html;
if(item.type==='choice'){const selected=Array.isArray(value)?value:[];html=`<fieldset class="exam-choice"><legend lang="en">${E(item.label)} <span class="meta">(${item.points} ${item.points===1?'Antwort':'Antworten'})</span></legend>${item.options.map((o,i)=>`<label class="choice"><input type="${item.points===1?'radio':'checkbox'}" name="${id}" data-exam="${y}" data-exam-choice="${item.id}" value="${i}" ${selected.includes(i)?'checked':''} ${disabled}><span lang="en">${E(o)}</span></label>`).join('')}</fieldset>`;if(s.submitted){const score=examChoiceScore(item,selected);html+=`<div class="feedback ${score===item.points?'correct':''}"><strong>${score} / ${item.points} BE automatisch geprüft</strong><p>Richtig: ${item.correct.map(i=>E(item.options[i])).join(' · ')}</p></div>`;}}
else{html=`<div class="field"><label for="${id}" lang="en">${E(item.label)}</label>${item.points>1?`<textarea id="${id}" data-exam="${y}" data-exam-listen="${item.id}" spellcheck="false" ${disabled}>${E(value||'')}</textarea>`:`<input id="${id}" type="text" data-exam="${y}" data-exam-listen="${item.id}" value="${E(value||'')}" autocomplete="off" spellcheck="false" ${disabled}>`}</div>`;if(s.submitted)html+=`<div class="feedback"><p><strong>Lösungshinweis:</strong> ${E(item.key)}</p><p class="meta">Sinnentsprechende Antworten zählen. Rechtschreibung nur berücksichtigen, wenn sie die Bedeutung verändert. Gleiche Aspekte nicht doppelt zählen.</p>${examSelfSelect(y,'l:'+item.id,item.points,'Deine Punkte · '+item.id,y===2022?1:.5)}</div>`;}
return html;}
function examChoiceScore(item,selected=[]){if(!Array.isArray(selected)||selected.length>item.points)return 0;return [...new Set(selected)].filter(i=>item.correct.includes(i)).length;}
function examPassage(y,p){const s=examState(y);return E(p.text).replace(/\{\{(\d+)\}\}/g,(_,id)=>{const g=EX[y].grammar.find(g=>g.id===id);return p.kind==='correction'?`<strong class="original-underline">${E(g.original)}<sup>${id}</sup></strong>`:`<label class="inline-gap"><span>Lücke ${id}</span><input type="text" aria-label="Lücke ${id}" data-exam="${y}" data-exam-grammar="${id}" value="${E(s.grammar[id]||'')}" autocomplete="off" autocapitalize="off" spellcheck="false" ${s.submitted?'disabled':''}></label>`;});}
function examCorrection(y,g){const s=examState(y);return `<div class="correction-row"><label for="eg-${g.id}"><strong>${g.id}. <span lang="en">${E(g.original)}</span></strong></label><input type="text" id="eg-${g.id}" data-exam="${y}" data-exam-grammar="${g.id}" value="${E(s.grammar[g.id]||'')}" placeholder="Deine Verbesserung" autocomplete="off" autocapitalize="off" spellcheck="false" ${s.submitted?'disabled':''}></div>`;}
function examGrammarCorrect(g,answer){return g.answers.some(a=>normalize(a,g.caseSensitive)===normalize(answer||'',g.caseSensitive));}
function examGrammarFeedback(y,g){const s=examState(y),correct=examGrammarCorrect(g,s.grammar[g.id]),t=topic(g.topic);return`<div class="feedback ${correct?'correct':''}"><h3>${g.id}. ${correct?'Richtig':'Noch einmal ansehen'}</h3><p>Deine Antwort: <strong>${E(s.grammar[g.id]||'nicht beantwortet')}</strong><br>Lösung: ${g.answers.map(E).join(' / ')}</p><p>${E(t.rule)}</p><a href="#grammar/${g.topic}">${E(t.title)} nachschlagen</a></div>`;}
function examSelfSelect(y,key,max,label,step){const s=examState(y);let values=[];for(let i=0;i<=max;i+=step)values.push(i);return `<div class="self-score"><label for="es-${key}">${E(label)}</label><select id="es-${key}" data-exam="${y}" data-exam-self="${key}"><option value="">Noch nicht eingeschätzt</option>${values.map(n=>`<option value="${n}" ${s.self[key]!==undefined&&s.self[key]!==''&&Number(s.self[key])===n?'selected':''}>${n.toLocaleString('de-DE')} / ${max} BE</option>`).join('')}</select></div>`;}
function examScore(y){const s=examState(y),e=EX[y];const grammar=e.grammar.filter(g=>examGrammarCorrect(g,s.grammar[g.id])).length,items=e.listening.flatMap(g=>g.items);const auto=items.filter(i=>i.type==='choice').reduce((sum,i)=>sum+examChoiceScore(i,s.listening[i.id]||[]),0),free=items.filter(i=>i.type==='text');const ungraded=free.filter(i=>s.self['l:'+i.id]===undefined||s.self['l:'+i.id]==='').length,manual=free.reduce((sum,i)=>sum+Number(s.self['l:'+i.id]||0),0);const writing=['content','language'].some(k=>s.self[k]===undefined||s.self[k]==='')?null:(Number(s.self.content)+Number(s.self.language))*2;return{grammar,listening:auto+manual,listeningAuto:auto,ungraded,writing,total:ungraded||writing===null?null:grammar+auto+manual+writing};}
function examResults(y){return`<section class="panel tint" id="exam-results" tabindex="-1"><h2>Deine Auswertung</h2><div id="exam-score-summary" aria-live="polite">${examSummary(y)}</div><p class="meta">Use of English und Ankreuzaufgaben sind automatisch geprüft. Freie Antworten und Schreibtext bewertest du selbst. Die Summe ist eine Selbsteinschätzung, keine offizielle Note.</p><div class="actions">${button('Hörantworten prüfen','exam-jump:listening','secondary')}${button('Grammatik ansehen','exam-jump:grammar','secondary')}${button('Schreibtext einschätzen','exam-jump:writing','secondary')}</div></section>`;}
function examSummary(y){const r=examScore(y);return`<ul><li><strong>Use of English: ${r.grammar} / 20 BE</strong> · automatisch geprüft</li><li>Hörverstehen: ${r.ungraded?`${r.listeningAuto} BE aus Ankreuzaufgaben; ${r.ungraded} freie Antworten noch selbst einschätzen`:`${r.listening.toLocaleString('de-DE')} / 20 BE einschließlich Selbsteinschätzung`}</li><li>Textproduktion: ${r.writing===null?'noch selbst einschätzen':r.writing+' / 20 BE selbst eingeschätzt'}</li></ul>${r.total===null?'<p>Die Gesamtsumme erscheint, wenn du alle freien Antworten eingeschätzt hast.</p>':`<p class="result-number">${r.total.toLocaleString('de-DE')} / 60 BE</p>`}`;}
function examRemaining(y){const t=examState(y).timer;return !t?3000:t.running?Math.max(0,Math.ceil((t.deadline-Date.now())/1000)):t.remaining;}
function examTimeLabel(y){const n=examRemaining(y);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function examSave(){const ok=save();const status=$('#exam-saved');if(status)status.textContent=ok?'Auf diesem Gerät gespeichert':'Speichern nicht verfügbar. Bitte Antwortbogen herunterladen.';}
function examExport(y){const s=examState(y),e=EX[y];let lines=[`English Lab · Klasse 7 · Originaltest ${y}`,`Stand: ${new Date().toLocaleString('de-DE')}`,s.submitted?'Abgegeben zur Selbstkontrolle':'Entwurf','\nI · LISTENING'];for(const g of e.listening){lines.push('\n'+g.title);for(const i of g.items){const val=s.listening[i.id];lines.push(i.label,i.type==='choice'?(val||[]).map(n=>i.options[n]).join(' / ')||'—':val||'—');}}lines.push('\nII · USE OF ENGLISH');for(const g of e.grammar)lines.push(`${g.id}. ${g.original?g.original+' → ':''}${s.grammar[g.id]||'—'}`);lines.push('\nIII · TEXT PRODUCTION','Planung:',s.plan,'Text:',s.writing,`Wörter: ${wordCount(s.writing)}`);if(s.submitted){const r=examScore(y);lines.push('\nAUSWERTUNG',`Grammatik: ${r.grammar}/20`,`Hörverstehen: ${r.listening}/20 (${r.ungraded} Antworten noch nicht selbst eingeschätzt)`,`Schreiben: ${r.writing??'offen'}/20 (Selbsteinschätzung)`,`Gesamt: ${r.total??'noch offen'}/60`);}download(`English-Lab-Klasse-7-${y}-Antworten.txt`,lines.join('\n'));}
document.addEventListener('input',event=>{const el=event.target,y=el.dataset.exam;if(!y||!EX[y])return;const s=examState(y);if(s.submitted)return;if(el.dataset.examListen)s.listening[el.dataset.examListen]=el.value;if(el.dataset.examGrammar)s.grammar[el.dataset.examGrammar]=el.value;if(['plan','writing'].includes(el.dataset.examField)){s[el.dataset.examField]=el.value;if(el.dataset.examField==='writing')$('#exam-word-count').textContent=wordCount(el.value)+' Wörter';}examSave();});
document.addEventListener('change',event=>{const el=event.target,y=el.dataset.exam;if(!y||!EX[y])return;const s=examState(y);if(el.dataset.examSelf){if(!s.submitted)return;const key=el.dataset.examSelf,item=EX[y].listening.flatMap(g=>g.items).find(i=>'l:'+i.id===key),max=key==='content'?4:key==='language'?6:item?.points;if(max===undefined)return;const value=el.value,step=key.startsWith('l:')&&Number(y)===2022?1:.5;if(value!==''&&(!Number.isFinite(Number(value))||Number(value)<0||Number(value)>max||Number(value)%step!==0))return;s.self[key]=value;examSave();if($('#exam-score-summary'))$('#exam-score-summary').innerHTML=examSummary(y);return;}if(s.submitted)return;if(el.dataset.examChoice){const key=el.dataset.examChoice,item=EX[y].listening.flatMap(g=>g.items).find(i=>i.id===key);const checked=[...document.querySelectorAll(`[data-exam-choice="${key}"]:checked`)].map(x=>Number(x.value));if(checked.length>item.points){el.checked=false;notify(`Bitte höchstens ${item.points} Antworten auswählen.`);return;}s.listening[key]=checked;examSave();}});
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const [action,v]=b.dataset.action.split(':');if(action==='exam-jump'){const el=$('#exam-'+v);if(el){el.open=true;el.scrollIntoView({block:'start'});el.querySelector('summary')?.focus();}return;}if(!action.startsWith('exam-')||!EX[v])return;const y=Number(v),s=examState(y);if(action==='exam-submit'){const total=EX[y].listening.flatMap(g=>g.items).length+EX[y].grammar.length+1,filled=examFilled(y);if(filled<total&&!confirm(`Es sind noch Antwortfelder leer (${filled} von ${total} bearbeitet). Trotzdem abgeben und Lösungen anzeigen?`))return;s.submitted=true;if(s.timer?.running)s.timer={running:false,remaining:examRemaining(y)};examSave();render(false);$('#exam-results').focus();$('#exam-results').scrollIntoView({block:'start'});return;}if(action==='exam-edit'){s.submitted=false;s.self={};examSave();render(false);notify('Antworten wieder bearbeitbar. Die Selbsteinschätzung wird bei der nächsten Abgabe neu vorgenommen.');return;}if(action==='exam-export'){examExport(y);return;}if(s.submitted)return;if(action==='exam-timer'){const left=examRemaining(y);s.timer=s.timer?.running?{running:false,remaining:left}:{running:true,deadline:Date.now()+(left||3000)*1000};examSave();b.textContent=s.timer.running?'Pausieren':'Timer starten / fortsetzen';return;}if(action==='exam-reset-timer'&&confirm('Timer dieses Tests auf 50 Minuten zurücksetzen?')){s.timer=null;examSave();$(`[data-exam-timer="${y}"]`).textContent=examTimeLabel(y);$(`[data-action="exam-timer:${y}"]`).textContent='Timer starten / fortsetzen';}});
setInterval(()=>{if(typeof state==='undefined')return;for(const [y,s] of Object.entries(state.exams)){if(!EX[y])continue;if(s.timer?.running&&examRemaining(y)===0){s.timer={running:false,remaining:0};save();notify(`Originaltest ${y}: Die 50 Minuten sind um. Du kannst jetzt abgeben.`);}const o=document.querySelector(`[data-exam-timer="${y}"]`);if(o)o.textContent=examTimeLabel(y);}},1000);
